#ifndef MINIMAP_MARKS_GLSL
#define MINIMAP_MARKS_GLSL

// Recognizing map faces. Needs nothing else, so Sodium's terrain shader can include it too.

// The heights of map faces, in 1/64 of a block (quarter model pixels): bit n set for n / 64.
// The same as MARKS in map_faces.py.
const uint MAP_MARKS_LOW = 0x2a002aa8u;    // n = 0..31
const uint MAP_MARKS_HIGH = 0x2aa800a8u;   // n = 32..63

// Whether a model coordinate (in blocks) is at one of the map-face heights.
bool isMark(float coordinate) {
    float q = fract(coordinate) * 64.0;
    float n = round(q);
    if (abs(q - n) > 0.01) {
        return false;
    }
    uint bit = uint(n);
    return bit < 32u ? ((MAP_MARKS_LOW >> bit) & 1u) != 0u : ((MAP_MARKS_HIGH >> (bit - 32u)) & 1u) != 0u;
}

#endif

#ifndef MINIMAP_GLSL
#define MINIMAP_GLSL

#include <minimap:marks.glsl>

// Shared by core/terrain (the capture) and the post effect (the memory and the map). Needs Globals.
//
// Every block model has a map face: a copy of its top face, inside the model, at a height no vanilla
// model uses (map_faces.py). terrain.vsh draws these faces into the capture square, one pixel per
// block, north up, around the camera's block. The post effect copies the capture into a memory where
// each texel is a block, then draws the round map from the memory over the capture square.

const int MAP_BLOCKS = 128;       // blocks across the capture square
const int MAP_MEMORY = 256;       // blocks across the memory (a power of two); its row 256 keeps the heading
const int MAP_RADIUS = 64;        // radius of the round map, in blocks
const int MAP_SCALE = 2;          // screen pixels per block on the map
const int MAP_MARGIN = 16;        // pixels between the map and the corner of the screen
const float MAP_TAG = 0.5;        // alpha of map texels in minecraft:main
const float MAP_HEADING_TAG = 0.25;   // alpha of the capture pixel that carries the heading

// Center of the round map, in pixels from the bottom-left corner of the screen.
ivec2 mapCenter() {
    return ivec2(ScreenSize) - ivec2(MAP_MARGIN + MAP_RADIUS * MAP_SCALE);
}

// The capture square sits in the middle of the round map, which covers it.
ivec2 captureOrigin() {
    return mapCenter() - ivec2(MAP_BLOCKS / 2);
}

// Pixel of the capture that holds the block at (x, z) from the camera's block.
ivec2 capturePixel(ivec2 rel) {
    return captureOrigin() + ivec2(MAP_BLOCKS / 2 + rel.x, MAP_BLOCKS / 2 - 1 - rel.y);
}

// Texel of the memory that holds a block, from its world x and z: the memory wraps around.
ivec2 memoryTexel(ivec2 world) {
    return world & (MAP_MEMORY - 1);
}

// Alpha of a memory texel: the 256-block region the block belongs to (0: never seen). A texel that
// wraps onto a block of another region is forgotten instead of showing the wrong place.
float memoryRegion(ivec2 world) {
    ivec2 region = (world >> 8) & 7;
    return float(1 + region.x + 8 * region.y) / 255.0;
}

// The heading, in turns clockwise from north, as 24 bits in RGB.
vec3 packHeading(float turns) {
    uint v = uint(fract(turns) * 16777216.0);
    return vec3(float(v >> 16u), float((v >> 8u) & 255u), float(v & 255u)) / 255.0;
}

float unpackHeading(vec3 rgb) {
    uvec3 b = uvec3(round(rgb * 255.0));
    return float((b.r << 16u) | (b.g << 8u) | b.b) / 16777216.0;
}

#endif

