layout(location = 4) out float chunkVisibility;
layout(location = 5) out vec4 screenClip;
layout(location = 6) out float mapFace;
layout(location = 7) out float mapSkyLight;

gl_Position = ProjMat * ModelViewMat * vec4(pos, 1.0);
screenClip = gl_Position;
mapFace = 0.0;
mapSkyLight = 0.0;
if (isMark(Position.x) || isMark(Position.z)) {
    // A map face turned on its side by the blockstate (logs, pistons...): not drawn.
    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
} else if (isMark(Position.y)) {
    // A map face: into the capture square. Its corners, from the camera's block, are whole numbers
    // in x and z, so each block covers exactly one pixel. North up; higher blocks in front (depth is
    // reversed). A map face turned upside down faces away here, and is culled.
    vec3 rel = Position + vec3(ChunkPosition - CameraBlockPos);
    vec2 pixel = vec2(captureOrigin()) + vec2(float(MAP_BLOCKS / 2) + rel.x, float(MAP_BLOCKS / 2) - rel.z);
    gl_Position = vec4(pixel / ScreenSize * 2.0 - 1.0, 0.5 + 0.4 * clamp(rel.y / 512.0, -1.0, 1.0), 1.0);
    screenClip = gl_Position;
    mapFace = 1.0;
    mapSkyLight = float(UV2.y) / 16.0;
    sphericalVertexDistance = 0.0;
    cylindricalVertexDistance = 0.0;
    vertexColor = Color;
    texCoord0 = UV0;
    chunkVisibility = 1.0;
    return;
}

layout(location = 4) in float chunkVisibility;
layout(location = 5) in vec4 screenClip;
layout(location = 6) in float mapFace;
layout(location = 7) in float mapSkyLight;

void main() {
    // The capture square only takes map faces, and map faces stay in it.
    vec2 pixel = (screenClip.xy / screenClip.w * 0.5 + 0.5) * ScreenSize;
    vec2 origin = vec2(captureOrigin());
    bool inCapture = all(greaterThanEqual(pixel, origin)) && all(lessThan(pixel, origin + float(MAP_BLOCKS)));
    if (inCapture != (mapFace > 0.5)) {
        discard;
    }
    if (mapFace > 0.5) {
        #ifdef ALPHA_CUTOUT
        if (ALPHA_CUTOUT < 0.3) {
            discard;   // translucent terrain (ice, stained glass): blending would change the tag
        }
        #endif
        #ifndef OIT_ALPHA_ONLY
        // The average color of the sprite (mip level 4 of a 16x16 sprite), with the tint and the ambient
        // occlusion, which shades the steps of the terrain.
        vec4 texel = textureLod(Sampler0, texCoord0, 4.0);
        if (texel.a < 0.25) {
            discard;   // mostly empty sprites (glass): the map shows what is below
        }
        vec3 color = texel.rgb * vertexColor.rgb;
        // Water has no map face. The top face of a column under water gets one level of sky light less
        // per block of water: tint it by that depth.
        float depth = 15.0 - mapSkyLight;
        if (depth > 0.5) {
            color = mix(color, vec3(0.17, 0.32, 0.66), clamp(0.55 + depth * 0.03, 0.0, 0.9));
        }
        fragColor = vec4(color, MAP_TAG);
        if (ivec2(pixel) == capturePixel(ivec2(0))) {
            // The camera's own column carries the heading instead: the camera's right vector, from the
            // view rotation, turned a quarter turn, in turns clockwise from north.
            vec3 right = vec3(ModelViewMat[0][0], ModelViewMat[1][0], ModelViewMat[2][0]);
            fragColor = vec4(packHeading(atan(right.z, right.x) / 6.2831853), MAP_HEADING_TAG);
        }
        return;
        #endif
    }

