#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <minimap:minimap.glsl>

// The memory, one texel per block: take the block from this frame's capture when it is there, keep
// what the memory had otherwise. Row MAP_MEMORY keeps the last heading.
uniform sampler2D MainSampler;
uniform sampler2D HistorySampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    ivec2 texel = ivec2(texCoord * vec2(MAP_MEMORY, MAP_MEMORY + 1));
    if (texel.y == MAP_MEMORY) {
        vec4 bus = texelFetch(MainSampler, capturePixel(ivec2(0)), 0);
        bool fresh = texel.x == 0 && abs(bus.a - MAP_HEADING_TAG) < 0.05;
        fragColor = fresh ? vec4(bus.rgb, 1.0) : texelFetch(HistorySampler, texel, 0);
        return;
    }
    // The block this texel holds: of the blocks that wrap onto it, the one nearest to the camera.
    ivec2 rel = ((texel - CameraBlockPos.xz + MAP_MEMORY / 2) & (MAP_MEMORY - 1)) - MAP_MEMORY / 2;
    ivec2 world = CameraBlockPos.xz + rel;
    float region = memoryRegion(world);
    fragColor = texelFetch(HistorySampler, texel, 0);
    if (abs(fragColor.a - region) > 0.5 / 255.0) {
        fragColor = vec4(0.0);   // a block of another place, or never seen
    }
    if (all(greaterThanEqual(rel, ivec2(-MAP_BLOCKS / 2))) && all(lessThan(rel, ivec2(MAP_BLOCKS / 2)))) {
        vec4 captured = texelFetch(MainSampler, capturePixel(rel), 0);
        if (abs(captured.a - MAP_TAG) < 0.05) {
            fragColor = vec4(captured.rgb, region);
        }
    }
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Copy with alpha: in the memory, alpha is the region of the block (0: never seen).
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = texture(InSampler, texCoord);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <minimap:minimap.glsl>

// The round map, drawn from the memory over the capture square: centered on the camera, turned so
// that the camera looks up, with an arrow for the camera and a red dot for north.
uniform sampler2D MainSampler;
uniform sampler2D MapSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

// Inside the triangle a, b, c (counterclockwise).
bool inTriangle(vec2 p, vec2 a, vec2 b, vec2 c) {
    vec3 e = vec3(cross(vec3(b - a, 0.0), vec3(p - a, 0.0)).z,
                  cross(vec3(c - b, 0.0), vec3(p - b, 0.0)).z,
                  cross(vec3(a - c, 0.0), vec3(p - c, 0.0)).z);
    return all(greaterThanEqual(e, vec3(0.0)));
}

void main() {
    ivec2 pixel = ivec2(texCoord * ScreenSize);
    fragColor = vec4(texelFetch(MainSampler, pixel, 0).rgb, 1.0);

    // No map until a heading has arrived: terrain has not drawn the capture yet, or can't (Sodium).
    vec4 stored = texelFetch(MapSampler, ivec2(0, MAP_MEMORY), 0);
    if (stored.a < 0.5) {
        return;
    }

    vec2 d = vec2(pixel) + 0.5 - vec2(mapCenter());   // from the center, y up
    float radius = float(MAP_RADIUS * MAP_SCALE);
    float r = length(d);
    if (r > radius + 3.0) {
        return;
    }
    if (r > radius) {
        fragColor = vec4(0.85, 0.82, 0.74, 1.0);   // rim
        return;
    }

    // Turn the map so that the heading points up. Map coordinates: x east, y north.
    float heading = unpackHeading(stored.rgb) * 6.2831853;
    vec2 forward = vec2(sin(heading), cos(heading));
    vec2 right = vec2(cos(heading), -sin(heading));
    vec2 offset = (d.x * right + d.y * forward) / float(MAP_SCALE);

    vec3 camera = vec3(CameraBlockPos) - CameraOffset;
    ivec2 world = ivec2(floor(camera.xz + vec2(offset.x, -offset.y)));
    vec4 block = texelFetch(MapSampler, memoryTexel(world), 0);
    bool known = abs(block.a - memoryRegion(world)) < 0.5 / 255.0;
    fragColor = vec4(known ? block.rgb : vec3(0.1, 0.1, 0.11), 1.0);

    // The camera: an arrow pointing up, white with a dark edge.
    vec2 tip = vec2(0.0, 9.0), left = vec2(-6.5, -7.0), notch = vec2(0.0, -3.0), rightCorner = vec2(6.5, -7.0);
    if (inTriangle(d, left * 1.35, notch * 1.35, tip * 1.35) || inTriangle(d, notch * 1.35, rightCorner * 1.35, tip * 1.35)) {
        fragColor = vec4(0.12, 0.12, 0.12, 1.0);
    }
    if (inTriangle(d, left, notch, tip) || inTriangle(d, notch, rightCorner, tip)) {
        fragColor = vec4(1.0);
    }

    // North: a red dot on the edge, where the map's north direction ends up on screen.
    vec2 north = vec2(-sin(heading), cos(heading)) * (radius - 9.0);
    if (length(d - north) < 5.5) {
        fragColor = vec4(0.85, 0.15, 0.12, 1.0);
    }
}

